	inline const G3D::Matrix3 Math::matrixTiltQuadrant(int quadrant)
	{
		switch (quadrant)
		{
		case 0:
			return G3D::Matrix3(1, 0, 0, 0, 0, -1, 0, 1, 0);
		case 1:
			return Math::matrixTiltZ();
