	G3D::Matrix3 Math::getIWorldAtPoint(const G3D::Vector3& cofmPos, const G3D::Vector3& worldPos, const G3D::Matrix3& iWorldAtCofm, float mass)
	{
		G3D::Vector3 delta = worldPos - cofmPos;
		float deltaXSquared = delta.x * delta.x;
		float deltaYSquared = delta.y * delta.y;
		float deltaZSquared = delta.z * delta.z;
		float deltaYX = delta.y * delta.x;
		float deltaZX = delta.z * delta.x;
		float deltaZY = delta.z * delta.y;

		return iWorldAtCofm + mass * G3D::Matrix3(
				deltaZSquared + deltaYSquared,
				-deltaYX,
				-deltaZX,
				-deltaYX,
				deltaZSquared + deltaXSquared,
				-deltaZY,
				-deltaZX,
				-deltaZY,
				deltaYSquared + deltaXSquared
				);
	}

	bool Math::intersectRayPlane(const G3D::Ray& ray, const G3D::Plane& plane, G3D::Vector3& hit)
	{
		float dotProd = ray.direction.dot(plane.normal());
		if (plane.halfSpaceContains(ray.origin))
		{
			if (!(dotProd < 0.0f))
			{
				hit = G3D::Vector3::inf();
				return false;
			}
		}
		else if (!(dotProd > 0.0f))
		{
			hit = G3D::Vector3::inf();
			return false;
		}
		G3D::Line myLine = G3D::Line::fromPointAndDirection(ray.origin, ray.direction);
		hit = myLine.intersection(plane);
		return true;
	}

	inline G3D::Vector3 Math::closestPointOnRay(const G3D::Ray& pointOnRay, const G3D::Ray& otherRay)
	{
		G3D::Vector3 pa = pointOnRay.origin;
		G3D::Vector3 pPlane = otherRay.origin;
		G3D::Vector3 ua = pointOnRay.direction;
		G3D::Vector3 ub = otherRay.direction;
		G3D::Vector3 p = pPlane - pa;
		float uaub = ua.dot(ub);
		float q1 = ua.dot(p);
		float q2 = -ub.dot(p);
		float d = 1 - uaub * uaub;
		if (d > 1e-5)
		{
			float alpha = (q1 + uaub * q2) / d;
			return pa + alpha * ua;
		}
		else
		{
			return pa;
		}
	}

	float Math::computeLaunchAngle(float speed, float distance, float height, float gravity)
	{
		double g = fabs(gravity);
		double disc = speed * speed * speed * speed
			- (distance * distance * g + 2.0 * (speed * speed) * height) * g;

		if (disc <= 0.0)
			return Math::pi() / 4;

		double root = sqrt(disc);
		double v2 = speed * speed;
		float upper = (float)atan((root + v2) / (distance * g));
		float lower = (float)atan((v2 - root) / (g * distance));
		return std::min(upper, lower);
	}

